/** The amudim filed under each chelek by the program. */
export const amudChalakim = [
  { chelek: 'Chelek 1', start: 1, end: 280 },
  { chelek: 'Chelek 2', start: 281, end: 579 },
  { chelek: 'Chelek 3', start: 580, end: 963 },
  { chelek: 'Chelek 4', start: 964, end: 1150 },
  { chelek: 'Chelek 5', start: 1151, end: 1435 },
  { chelek: 'Chelek 6', start: 1436, end: 1750 }
];

export const AMUD_COUNT = AMUD_STARTS.length;

/**
 * Details of one amud, or null outside 1-AMUD_COUNT.
 * @returns {{ amud: number, siman: number, seif: number | null, chelek: string } | null}
 */
export function amudInfo(amud) {
  const n = Number(amud);
  if (!Number.isInteger(n) || n < 1 || n > AMUD_STARTS.length) return null;
  const [siman, seif] = AMUD_STARTS[n - 1].split(':');
  const { chelek } = amudChalakim.find((c) => n >= c.start && n <= c.end);
  return { amud: n, siman: Number(siman), seif: seif === undefined ? null : Number(seif), chelek };
}

/** Where an amud starts, as "siman:se'if" (or the bare siman for a review amud). */
export function amudStart(amud) {
  const info = amudInfo(amud);
  if (!info) return '';
  return info.seif === null ? `${info.siman}` : `${info.siman}:${info.seif}`;
}

/** Row label for a chart: amud number, then where it starts. */
export function amudLabel(amud) {
  const info = amudInfo(amud);
  return info ? `${info.amud} · ${amudStart(amud)}` : String(amud);
}

// Orders amud starts; a review amud (no se'if) follows every se'if of its siman.
const startKey = (info) => [info.siman, info.seif === null ? Infinity : info.seif];
const before = (a, b) => a[0] < b[0] || (a[0] === b[0] && a[1] < b[1]);

/**
 * The amudim that cover simanim startSiman-endSiman, as { start, end }: from
 * the amud in which startSiman begins (which may open partway through the
 * previous siman) to the last amud that starts at or before endSiman.
 */
export function amudRangeForSimanim(startSiman, endSiman) {
  const from = [Number(startSiman), 1];
  const to = Number(endSiman);
  if (!(from[0] >= 1) || !(to >= from[0])) return null;

  // First amud starting at or after startSiman:1. If it starts exactly there
  // it is the first amud of the range; otherwise startSiman begins inside the
  // amud before it.
  let start = AMUD_STARTS.length;
  for (let n = 1; n <= AMUD_STARTS.length; n++) {
    if (!before(startKey(amudInfo(n)), from)) {
      const key = startKey(amudInfo(n));
      start = key[0] === from[0] && key[1] === from[1] ? n : Math.max(n - 1, 1);
      break;
    }
  }

  let end = start;
  for (let n = start; n <= AMUD_STARTS.length && amudInfo(n).siman <= to; n++) end = n;
  return { start, end };
}
